package com.atlashub.pay.txquery.application.commands;
import com.atlashub.pay.txquery.application.commands.ProjectChargeTransaction.*;import com.atlashub.pay.txquery.application.services.TransactionProjectionSupport;import com.atlashub.pay.txquery.domain.entities.TransactionRecord;import com.atlashub.pay.txquery.domain.repositories.TransactionRecordRepository;import com.atlashub.pay.txquery.domain.valueobject.TransactionStatus;import com.atlashub.shared.application.security.ApiEnvironment;import com.atlashub.shared.domain.valueobject.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.ZonedDateTime;import java.util.Optional;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class ProjectChargeTransactionHandlerTest {@Test void createsCustomerChargeProjection(){var repo=mock(TransactionRecordRepository.class);when(repo.findByOrganizationIdAndEnvironmentAndReference(1L,ApiEnvironment.TEST,"ref")).thenReturn(Optional.empty());when(repo.nextIdentity()).thenReturn(10L);when(repo.save(any())).thenAnswer(i->i.getArgument(0));var handler=new ProjectChargeTransactionHandler(new TransactionProjectionSupport(repo));handler.execute(new ProjectChargeTransactionCommand(1L,"TEST","ref",Money.of(new BigDecimal("100"),CurrencyCode.NGN),Money.of(BigDecimal.ONE,CurrencyCode.NGN),"CARD","PAYSTACK","COMMERCE_CHECKOUT","order","customer",TransactionStatus.SUCCESSFUL,null,ZonedDateTime.now()));var captor=org.mockito.ArgumentCaptor.forClass(TransactionRecord.class);verify(repo,atLeastOnce()).save(captor.capture());assertEquals("customer",captor.getValue().getPartyReferenceId());assertEquals(new BigDecimal("99.0000"),captor.getValue().getNetAmount().amount());}}
